<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';import type{OrderProjection}from'../../domain/types'
const p=ref<OrderProjection|null>(null),orderRef=ref(''),loading=ref(false),error=ref('');const rConfirmed=computed(()=>p.value?.facts.refund==='CONFIRMED');const lClosed=computed(()=>p.value?.facts.accounting==='CONFIRMED');const lateConflict=computed(()=>rConfirmed.value&&p.value?.facts.delivery==='CONFIRMED');async function refresh(){if(!orderRef.value){error.value='暂时无法找到该订单。';return}loading.value=true;error.value='';try{p.value=await api.getProjection(orderRef.value)}catch{p.value=null;error.value='暂时无法更新退款进度，请稍后重试。'}finally{loading.value=false}}onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()})
</script>
<template><view class="page"><AppHeader left="订单" @left="uni.navigateBack()"/><view class="content"><view class="heading" role="heading" aria-level="1">退款进度</view><text class="desc">退款到账可能需要一些时间，我们会持续更新结果。</text><StatusNotice v-if="error" tone="unknown" title="暂时无法更新">{{error}}</StatusNotice><StatusNotice v-if="rConfirmed&&!lClosed" tone="unknown" title="退款已提交，正在核对">无需再次申请退款，请稍后查询。</StatusNotice><StatusNotice v-if="lateConflict" tone="risk" title="订单需要人工协助">充值与退款状态出现变化，我们正在核对，不会重复操作。</StatusNotice><view class="card"><view class="kv"><text>退款状态</text><text>{{rConfirmed?'退款已确认':'正在处理'}}</text></view><view class="kv"><text>到账状态</text><text>{{p?.facts.delivery==='CONFIRMED'?'充值已到账':'等待确认'}}</text></view></view></view><view class="action"><button class="primary" :disabled="loading||!orderRef" @click="refresh">查询退款进度</button><button class="secondary" @click="uni.navigateTo({url:'/pages/support/case'})">联系帮助</button></view></view></template><style src="../../styles/shared.css"></style>
